ALTER TABLE "role"
    ADD COLUMN "code" varchar(100),
    ADD COLUMN "is_system" boolean NOT NULL DEFAULT false,
    ADD COLUMN "self_assignable" boolean NOT NULL DEFAULT false;

UPDATE "role"
SET "code" = 'role_' || "id"
WHERE "code" IS NULL;

ALTER TABLE "role"
    ALTER COLUMN "code" SET NOT NULL,
    ADD CONSTRAINT "role_code_key" UNIQUE ("code");

CREATE TABLE "permission" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "code" varchar(100) UNIQUE NOT NULL,
    "description" varchar(250) NOT NULL,
    "created_at" timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE "role_permission" (
    "role_id" bigint NOT NULL,
    "permission_id" bigint NOT NULL,
    "granted_at" timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY ("role_id", "permission_id"),
    CONSTRAINT "role_permission_role_id_fkey"
        FOREIGN KEY ("role_id") REFERENCES "role" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE,
    CONSTRAINT "role_permission_permission_id_fkey"
        FOREIGN KEY ("permission_id") REFERENCES "permission" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE
);

CREATE INDEX "role_user_user_id_idx" ON "role_user" ("user_id");
CREATE INDEX "role_permission_permission_id_idx" ON "role_permission" ("permission_id");
